<script setup lang="ts">
import { computed,reactive,ref } from 'vue';import { useMutation,useQuery,useQueryClient } from '@tanstack/vue-query';import { ElDialog,ElMessage } from 'element-plus';import { useRoute } from 'vue-router'
import { skillsApi } from '@/api/endpoints/assets';import type { SkillResponse,SkillScope,SkillCompositionResponse } from '@/api/types';import EmptyState from '@/components/base/EmptyState.vue';import ErrorState from '@/components/base/ErrorState.vue';import LoadingState from '@/components/base/LoadingState.vue';import ProblemAlert from '@/components/base/ProblemAlert.vue';import { queryKeys } from '@/queries/keys'
const route=useRoute(),client=useQueryClient(),projectId=computed(()=>String(route.params.projectId??''));const query=useQuery({queryKey:computed(()=>queryKeys.skills(projectId.value)),queryFn:()=>skillsApi.list(projectId.value)});const open=ref(false),editing=ref<SkillResponse>(),localError=ref(''),composition=ref<SkillCompositionResponse>();const form=reactive({name:'',description:'',rules:'style=克制',enabled:true,scope:'PROJECT' as SkillScope,chapterId:''});function parseRules(){const rules:Record<string,string>={};for(const line of form.rules.split('\n')){const [key,...rest]=line.split('=');if(!key?.trim()||!rest.join('=').trim())throw new Error('每条规则必须使用 key=value 格式');rules[key.trim()]=rest.join('=').trim()}return rules}const mutation=useMutation({mutationFn:()=>{const body={name:form.name.trim(),description:form.description.trim()||null,rules:parseRules(),enabled:form.enabled,scope:form.scope,chapterId:form.scope==='CHAPTER'?form.chapterId||null:null};return editing.value?skillsApi.update(editing.value.id,{...body,expectedVersion:editing.value.version}):skillsApi.create(projectId.value,body)},onSuccess:async()=>{await client.invalidateQueries({queryKey:queryKeys.skills(projectId.value)});open.value=false;ElMessage.success('Skill 已保存')}});function show(x?:SkillResponse){editing.value=x;localError.value='';Object.assign(form,x?{name:x.name,description:x.description??'',rules:Object.entries(x.rules).map(([k,v])=>`${k}=${v}`).join('\n'),enabled:x.enabled,scope:x.scope,chapterId:x.chapterId??''}:{name:'',description:'',rules:'style=克制',enabled:true,scope:'PROJECT',chapterId:''});open.value=true}async function save(){localError.value='';try{await mutation.mutateAsync()}catch(e){if(e instanceof Error&&!mutation.isError.value)localError.value=e.message}}async function compose(){try{composition.value=await skillsApi.compose(projectId.value)}catch{ElMessage.error('合成预览失败')}}
</script>
<template><main class="page-container"><header class="page-header"><div><p class="eyebrow">Skills</p><h1 tabindex="-1">Skill</h1><p>维护 BASE、PROJECT 与 CHAPTER 三层确定性规则。</p></div><div class="project-header-actions"><button class="sw-button sw-button--secondary" @click="compose">合成预览</button><button class="sw-button sw-button--primary" @click="show()">新建 Skill</button></div></header><div v-if="composition" class="composition-panel"><strong>{{ composition.resolved?'规则已解析':'存在同层冲突' }}</strong><p>{{ Object.keys(composition.effectiveRules).length }} 条有效规则，{{ composition.conflicts.length }} 个冲突。</p></div><LoadingState v-if="query.isPending.value"/><ErrorState v-else-if="query.isError.value" :error="query.error.value" @retry="query.refetch()"/><EmptyState v-else-if="!query.data.value?.length" title="还没有 Skill" description="创建第一组写作规则。"><button class="sw-button sw-button--primary" @click="show()">创建 Skill</button></EmptyState><section v-else class="asset-grid"><article v-for="x in query.data.value" :key="x.id" class="asset-card"><div class="asset-card-heading"><div><span class="asset-type">{{ x.scope }}</span><h2>{{ x.name }}</h2></div><span class="status-pill">{{ x.enabled?'启用':'停用' }}</span></div><p>{{ x.description||'无说明' }}</p><dl class="rules-list"><div v-for="(value,key) in x.rules" :key="key"><dt>{{ key }}</dt><dd>{{ value }}</dd></div></dl><div class="asset-actions"><button @click="show(x)">编辑规则</button></div></article></section><ElDialog v-model="open" :title="editing?'编辑 Skill':'新建 Skill'" width="min(620px,94vw)"><div v-if="localError" class="problem-alert">{{ localError }}</div><ProblemAlert v-if="mutation.isError.value" :error="mutation.error.value"/><form id="skill-form" class="sw-form" @submit.prevent="save"><label class="form-field"><span>名称</span><input v-model="form.name" maxlength="120" required/></label><label class="form-field"><span>说明</span><textarea v-model="form.description" rows="3" maxlength="1000"/></label><label class="form-field"><span>作用域</span><select v-model="form.scope"><option>BASE</option><option>PROJECT</option><option>CHAPTER</option></select></label><label v-if="form.scope==='CHAPTER'" class="form-field"><span>章节 UUID</span><input v-model="form.chapterId" required/></label><label class="form-field"><span>规则（每行 key=value）</span><textarea v-model="form.rules" rows="8" required/></label><label class="check-field"><input v-model="form.enabled" type="checkbox"/>启用</label></form><template #footer><button class="sw-button sw-button--secondary" @click="open=false">取消</button><button class="sw-button sw-button--primary" form="skill-form">保存</button></template></ElDialog></main></template>
